import { ContextMenu as TamaguiContextMenu, type Menu, withStaticProperties } from 'tamagui'
import { createMenuParts } from '../dropdown-menu/menuParts'
import type { ContextMenuProps, ContextMenuTriggerProps } from './types'

// Web: Tamagui's context menu — the menu opens at the pointer on right-click
// (or Shift+F10 / the Menu key) and after a long-press on touch screens.
// iOS / Android: see ContextMenu.native.tsx (long-press opens a bottom sheet).

// Same parts API as Menu, typed per primitive; the item styling is shared.
const parts = createMenuParts(TamaguiContextMenu as unknown as typeof Menu)

// Tamagui already flips the menu and keeps it inside the viewport by default.
function ContextMenuRoot({ children, onOpenChange }: ContextMenuProps) {
  return (
    <TamaguiContextMenu onOpenChange={(open: boolean) => onOpenChange?.(open)}>
      {children}
    </TamaguiContextMenu>
  )
}

function ContextMenuTrigger({ children, disabled = false, ...props }: ContextMenuTriggerProps) {
  return (
    <TamaguiContextMenu.Trigger
      disabled={disabled}
      // Tamagui renders a span; lay it out like any other block.
      display="flex"
      flexDirection="column"
      {...props}
    >
      {children}
    </TamaguiContextMenu.Trigger>
  )
}

/**
 * Actions for an area, opened with a right-click on desktop and a long-press
 * on touch screens. Offer the same actions somewhere visible too: context
 * menus are hidden until someone thinks to look for them.
 */
export const ContextMenu = withStaticProperties(ContextMenuRoot, {
  Trigger: ContextMenuTrigger,
  ...parts,
})

export type {
  ContextMenuCheckboxItemProps,
  ContextMenuContentProps,
  ContextMenuGroupProps,
  ContextMenuItemProps,
  ContextMenuLabelProps,
  ContextMenuProps,
  ContextMenuRadioGroupProps,
  ContextMenuRadioItemProps,
  ContextMenuTriggerProps,
} from './types'

import { View, withStaticProperties } from 'tamagui'
import { sheetMenu, useSheetMenu } from '../dropdown-menu/sheetMenu'
import type { ContextMenuProps, ContextMenuTriggerProps } from './types'

// iOS / Android: a long-press on the area opens Dropdown Menu's bottom sheet.

const { Root, ...parts } = sheetMenu

function ContextMenuRoot({ children, onOpenChange }: ContextMenuProps) {
  return <Root onOpenChange={onOpenChange}>{children}</Root>
}

function ContextMenuTrigger({ children, disabled = false, ...props }: ContextMenuTriggerProps) {
  const { setOpen } = useSheetMenu()
  return (
    <View
      // Screen readers cannot long-press an area they don't focus, so the area
      // is one element whose "long press" action (listed by VoiceOver and
      // TalkBack) opens the menu.
      accessible
      accessibilityHint={disabled ? undefined : 'Long press for options'}
      accessibilityActions={disabled ? undefined : [{ name: 'longpress', label: 'Options' }]}
      onAccessibilityAction={(event: { nativeEvent: { actionName: string } }) => {
        if (event.nativeEvent.actionName === 'longpress') setOpen(true)
      }}
      onLongPress={disabled ? undefined : () => setOpen(true)}
      {...props}
    >
      {children}
    </View>
  )
}

export const ContextMenu = withStaticProperties(ContextMenuRoot, {
  Trigger: ContextMenuTrigger,
  ...parts,
})

export type {
  ContextMenuCheckboxItemProps,
  ContextMenuContentProps,
  ContextMenuGroupProps,
  ContextMenuItemProps,
  ContextMenuLabelProps,
  ContextMenuProps,
  ContextMenuRadioGroupProps,
  ContextMenuRadioItemProps,
  ContextMenuTriggerProps,
} from './types'

import type { ReactNode } from 'react'
import type { GetProps, View } from 'tamagui'
import type {
  DropdownMenuCheckboxItemProps,
  DropdownMenuContentProps,
  DropdownMenuGroupProps,
  DropdownMenuItemProps,
  DropdownMenuLabelProps,
  DropdownMenuRadioGroupProps,
  DropdownMenuRadioItemProps,
} from '../dropdown-menu/types'

// Shared by ContextMenu.tsx (web) and ContextMenu.native.tsx. The items are
// Dropdown Menu's, so both menus look and behave the same once open.

export interface ContextMenuProps {
  children: ReactNode
  /** Called when the menu opens (right-click or long-press) or closes. */
  onOpenChange?: (open: boolean) => void
}

export interface ContextMenuTriggerProps extends Omit<GetProps<typeof View>, 'children'> {
  /** The area that opens the menu: a card, a row, a canvas… */
  children: ReactNode
  /** Ignore right-click and long-press. */
  disabled?: boolean
}

export type ContextMenuContentProps = DropdownMenuContentProps
export type ContextMenuItemProps = DropdownMenuItemProps
export type ContextMenuCheckboxItemProps = DropdownMenuCheckboxItemProps
export type ContextMenuRadioGroupProps = DropdownMenuRadioGroupProps
export type ContextMenuRadioItemProps = DropdownMenuRadioItemProps
export type ContextMenuLabelProps = DropdownMenuLabelProps
export type ContextMenuGroupProps = DropdownMenuGroupProps
